// Format anomalies as Telegram alert messages
// Refs: docs/specs/devrel-analytics-stack.md (AC-15)
// Pattern: alert_emit info 'anomaly: <content_piece> 5x baseline'
const anomalies = $input.all();
const messages = anomalies.map(item => {
  const a = item.json;
  const title = a.title || a.content_id;
  const platform = (a.platform || '').toUpperCase();
  const engagement = parseInt(a.last_hour_engagement || 0);
  const baseline = parseFloat(a.avg_engagement || 0);
  const multiple = baseline > 0 ? (engagement / baseline).toFixed(1) : 'N/A';
  const url = a.url ? `\n🔗 ${a.url}` : '';

  return {
    alert_text: `🚨 [DevRel Anomaly] ${platform}: "${title}"\n📈 ${engagement} engagements (${multiple}x baseline)${url}`,
    content_id: a.content_id,
    platform: a.platform,
    multiple
  };
});

return messages.map(m => ({ json: m }));
